/**
 * Cari card ID berdasarkan keyword (case-insensitive, exact match pada salah satu keyword kartu).
 * @param {string} keyword
 * @returns {string[]} array of card id
 */
export function findCardIdsByKeyword(keyword) {
  return KEYWORD_INDEX[keyword.toLowerCase()] ?? [];
}

/**
 * Ambil semua keyword unik yang ada di seluruh 78 kartu (buat autocomplete/filter chip).
 * @returns {string[]}
 */
export function getAllKeywords() {
  return Object.keys(KEYWORD_INDEX).sort();
}
